    union() {
        cylinder(h = base_t, r = base_r);                 // base disk
        cylinder(h = base_t + wall_h, r = outer_r);       // cradling wall
    }
    translate([0, 0, base_t])
        cylinder(h = wall_h + 1, r = inner_r);            // pocket the bottle sits in
