            translate([d / 2, 0, -1]) cylinder(h = h + 2, d = fd, $fn = 16);
    translate([0, 0, -1]) intersection() {                                              // shaft bore, D-flat on +x
        cylinder(h = h + 2, d = bore);
        translate([-d, -d, 0]) cube([d + bore / 2 - fl, 2 * d, h + 2]);
    }
}
