// Box with a press-fit lid - a hollow rectangular box (open top) and a separate lid whose plug
// drops into the opening. The two parts are laid side by side. NOVEL general part.
//

il   = 28.4;
iw   = 51.5;
ih   = 37.2;
wall = 3.9;
lip  = 5.8;

