    linear_extrude(t) rounded_rect(L, W, r);
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * (L / 2 - inset), sy * (W / 2 - inset), 0]) {
            translate([0, 0, -1]) cylinder(h = t + 2, d = screw);                       // shank
            translate([0, 0, t - csk]) cylinder(h = csk + 0.01, d1 = screw, d2 = head); // countersink
        }
}
