    // open the front: remove the +y half of the wall above the lower third,
    // leaving a C-shaped cradle the bottle slides into
    translate([-(inner_r + 1), 0, base_t + wall_h / 3])
        cube([2 * (inner_r + 1), base_r + 2, wall_h + 1]);
}
