t     = 4.3;
r     = 8;
screw = 3;

$fn = 48;

inset = r + 2;                     // hole-centre inset from the edges
head  = screw * 2;                 // countersink top diameter
csk   = min(screw, t - 1);         // countersink depth

module rounded_rect(l, w, rad) {
    offset(r = rad) square([l - 2 * rad, w - 2 * rad], center = true);
