fl    = min(flat, bore / 2 - 0.8); // keep the D-flat shallower than the bore radius

difference() {
    union() {
        cylinder(h = h - chamf + 0.01, d = d);                                          // body
        translate([0, 0, h - chamf]) cylinder(h = chamf, d1 = d, d2 = d - 2 * chamf);   // chamfered top
